package cn.minidayz.patcher;
import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.*;import java.nio.charset.*;import java.security.*;import org.json.*;
/** Bounded text edits on an already signed compatible module. Never patch native code by guessing. */
public final class AiWorkspace {
 public static String hash(byte[] b)throws Exception{return FilesEx.hex(MessageDigest.getInstance("SHA-256").digest(b));}
 public static boolean allowed(String n){return FilesEx.safeName(n)&&n.startsWith("assets/")&&(n.endsWith(".json")||n.endsWith(".js")||n.endsWith(".txt")||n.endsWith(".csv")||n.endsWith(".xml")||n.endsWith(".lua"))&&!n.contains("/Managed/");}
 public static String utf8(byte[] b)throws Exception{String s=Charset.forName("UTF-8").newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();FilesEx.require(s.indexOf('\0')<0,"E_AI_BINARY");return s;}
 public static byte[] current(Jobs j,String entry)throws Exception{FilesEx.require(allowed(entry),"E_AI_SCOPE: 仅支持 assets 内 UTF-8 文本配置和脚本，底层代码需人工处理");PatchEngine.Plan plan=j.engine().inspect(j.file(1),j.file(2),j);byte[] b;ZipFile src=new ZipFile(j.file(1));try{ZipEntry e=src.getEntry(entry);FilesEx.require(e!=null&&e.getSize()<=196608,"E_AI_FILE: 文件不存在或超过192KB");b=FilesEx.read(src.getInputStream(e),196608);}finally{src.close();}ZipFile mod=new ZipFile(j.file(2));try{JSONArray modules=plan.profile.getJSONArray("modules");for(int i=0;i<modules.length();i++){JSONArray ops=modules.getJSONObject(i).getJSONArray("operations");for(int k=0;k<ops.length();k++){JSONObject op=ops.getJSONObject(k);if(!entry.equals(op.getString("entry")))continue;FilesEx.require(op.getLong("after_size")<=196608&&hash(b).equals(op.getString("before_sha256")),"E_AI_PREIMAGE");ByteArrayOutputStream out=new ByteArrayOutputStream();JSONArray cmds=op.getJSONArray("commands");for(int t=0;t<cmds.length();t++){JSONObject cmd=cmds.getJSONObject(t);if(cmd.has("copy")){JSONArray c=cmd.getJSONArray("copy");out.write(b,c.getInt(0),c.getInt(1));}else{String path=cmd.getString("data");byte[] data=FilesEx.read(mod.getInputStream(mod.getEntry(path)),196608);FilesEx.require(hash(data).equals(plan.module.getJSONObject("payloads").getJSONObject(path).getString("sha256")),"E_PAYLOAD_HASH");out.write(data);}}b=out.toByteArray();FilesEx.require(b.length==op.getLong("after_size")&&hash(b).equals(op.getString("after_sha256")),"E_AI_POSTIMAGE");}}}finally{mod.close();}utf8(b);return b;}
 public static String logs(InputStream input)throws Exception{byte[] bytes=FilesEx.read(input,4194304);ByteArrayOutputStream out=new ByteArrayOutputStream();if(bytes.length>2&&bytes[0]=='P'&&bytes[1]=='K'){ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(bytes));try{int count=0;ZipEntry e;while((e=z.getNextEntry())!=null){FilesEx.require(++count<=200,"E_LOG_ZIP_LIMIT");String n=e.getName().toLowerCase(Locale.US);if(e.isDirectory()||!(n.endsWith(".log")||n.endsWith(".txt")||n.endsWith(".json"))||n.contains("key")||n.contains("secret"))continue;ByteArrayOutputStream one=new ByteArrayOutputStream();byte[] buf=new byte[8192];int nread;while((nread=z.read(buf))!=-1){FilesEx.require(one.size()+nread<=196608,"E_LOG_LIMIT");one.write(buf,0,nread);}byte[] b=one.toByteArray();byte[] label=("\n--- "+e.getName()+" ---\n").getBytes("UTF-8");FilesEx.require(out.size()+b.length+label.length<=393216,"E_LOG_LIMIT: 日志解压总量超过384KB，请缩小范围");out.write(label);out.write(b);}}finally{z.close();}}else{FilesEx.require(bytes.length<=393216,"E_LOG_LIMIT: 文本日志超过384KB");out.write(bytes);}return AiClient.redact(utf8(out.toByteArray()),null);}
 public static String validate(JSONObject proposal,String original)throws Exception{FilesEx.require(proposal.has("summary")&&proposal.has("before")&&proposal.has("after"),"E_AI_PROPOSAL: AI 未返回可执行修改，仅保留分析");String before=proposal.getString("before"),after=proposal.getString("after");FilesEx.require(before.length()>0&&!before.equals(after)&&original.indexOf(before)>=0&&original.indexOf(before)==original.lastIndexOf(before),"E_AI_ANCHOR: 原文必须唯一匹配，禁止猜测修改位置");String changed=original.replace(before,after);FilesEx.require(changed.getBytes("UTF-8").length<=196608,"E_AI_SIZE");return changed;}
 public static File apply(Jobs j,JSONObject p,String entry,String apkSha,String moduleSha)throws Exception{FilesEx.require(j.keyReady,"E_KEY_MISSING: 导出签名插件需导入原签名文件");FilesEx.require(FilesEx.sha(j.file(1),j).equals(apkSha)&&FilesEx.sha(j.file(2),j).equals(moduleSha),"E_AI_STALE: 输入已变化，请重新分析");byte[] before=current(j,entry);String afterText=validate(p,utf8(before));if(entry.endsWith(".json")){StrictJson.check(afterText);String t=afterText.trim();if(t.startsWith("["))new JSONArray(t);else new JSONObject(t);}if(entry.endsWith(".xml")){javax.xml.parsers.DocumentBuilderFactory f=javax.xml.parsers.DocumentBuilderFactory.newInstance();f.setExpandEntityReferences(false);FilesEx.require(!afterText.contains("<!DOCTYPE")&&!afterText.contains("<!ENTITY"),"E_AI_XML_ENTITY");f.newDocumentBuilder().parse(new ByteArrayInputStream(afterText.getBytes("UTF-8")));}byte[] after=afterText.getBytes("UTF-8");PatchEngine.Plan plan=j.engine().inspect(j.file(1),j.file(2),j);JSONObject m=new JSONObject(plan.module.toString());JSONArray profiles=m.getJSONArray("profiles");JSONObject profile=null;for(int i=0;i<profiles.length();i++)if(profiles.getJSONObject(i).getString("id").equals(plan.profile.getString("id")))profile=profiles.getJSONObject(i);FilesEx.require(profile!=null,"E_AI_PROFILE");JSONArray modules=profile.getJSONArray("modules"),deps=new JSONArray();for(int i=0;i<modules.length();i++)deps.put(modules.getJSONObject(i).getString("id"));String blob="payload/"+hash(after);m.getJSONObject("payloads").put(blob,new JSONObject().put("size",after.length).put("sha256",hash(after)));JSONObject op=new JSONObject().put("entry",entry).put("before_sha256",hash(before)).put("before_size",before.length).put("after_sha256",hash(after)).put("after_size",after.length).put("commands",new JSONArray().put(new JSONObject().put("data",blob)));modules.put(new JSONObject().put("id","ai-"+System.currentTimeMillis()).put("name","AI 文本修改（待实测）").put("mandatory",true).put("depends_on",deps).put("operations",new JSONArray().put(op)));m.put("version",m.getString("version")+"-ai");byte[] raw=m.toString(2).getBytes("UTF-8");Signing.Identity id=Signing.identity(FilesEx.read(new FileInputStream(j.file(3)),262144));Signature sig=Signature.getInstance("SHA256withRSA");sig.initSign(id.key);sig.update(raw);File dest=new File(j.root,"ai-module.pending.zip");ZipOutputStream out=new ZipOutputStream(new FileOutputStream(dest));ZipFile old=new ZipFile(j.file(2));try{Enumeration<? extends ZipEntry> es=old.entries();while(es.hasMoreElements()){FilesEx.check(j);ZipEntry e=es.nextElement();if(e.getName().equals("module.json")||e.getName().equals("module.sig")||e.getName().equals(blob)||e.getName().equals("AI_CHANGE.json"))continue;out.putNextEntry(new ZipEntry(e.getName()));InputStream in=old.getInputStream(e);try{FilesEx.copy(in,out,j);}finally{in.close();}out.closeEntry();}put(out,blob,after);put(out,"module.json",raw);put(out,"module.sig",sig.sign());put(out,"AI_CHANGE.json",new JSONObject().put("summary",p.getString("summary")).put("entry",entry).put("validation","哈希和模块结构通过；脚本需游戏实测").put("before_sha256",hash(before)).put("after_sha256",hash(after)).toString(2).getBytes("UTF-8"));}finally{out.close();old.close();}j.engine().inspect(j.file(1),dest,j);FilesEx.check(j);String modifiedModuleSha=FilesEx.sha(dest,j);File backup=new File(j.root,"ai-backup.zip");copy(j.file(2),backup,j);FilesEx.atomic(dest,j.file(2));OutputProvenance.imported(j.ctx.getSharedPreferences("local",0),2,modifiedModuleSha,j.output!=null&&j.output.isFile());j.plan=null;try{if(!j.report.optBoolean("replay_rule")){new RepairRules(j.root).remember(p,entry,apkSha,moduleSha,FilesEx.sha(j.file(2),j),hash(before),hash(after));j.report.put("repair_rule_saved",true);}}catch(Exception ruleError){j.report.put("repair_rule_saved",false);}return j.file(2);}
 static void put(ZipOutputStream z,String n,byte[] b)throws Exception{z.putNextEntry(new ZipEntry(n));z.write(b);z.closeEntry();}
 static void copy(File a,File b,Jobs j)throws Exception{File pending=new File(b.getPath()+".pending");InputStream in=new FileInputStream(a);OutputStream out=new FileOutputStream(pending);try{FilesEx.copy(in,out,j);}finally{in.close();out.close();}FilesEx.atomic(pending,b);}
}
